*** Settings ***
Library    String
Library    Collections

*** Test Cases ***
Parse Communication Logs
    @{raw_logs}=    Create List
    ...    ${SPACE}${SPACE}2025-10-04 14:30:15 | ERROR | NAV-101 | Navigation system offline${SPACE}${SPACE}
    ...    2025-10-04 14:31:22|WARN|PWR-205|Power fluctuation detected
    ...    ${SPACE}${SPACE}2025-10-04 14:32:10 | INFO | SYS-100 | System diagnostic complete${SPACE}${SPACE}
    ...    2025-10-04 14:33:45|ERROR|ENG-350|Engine temperature critical
    ...    ${SPACE}${SPACE}2025-10-04 14:34:00 | INFO | NAV-102 | Navigation restored${SPACE}${SPACE}
    @{parsed_logs}=    Create List
    FOR    ${log}    IN    @{raw_logs}
        ${clean_log}=    Strip String    ${log}
        @{fields}=    Split String    ${clean_log}    |
        ${timestamp}=    Strip String    ${fields}[0]
        ${level}=    Strip String    ${fields}[1]
        ${level}=    Convert To Upper Case    ${level}
        ${code}=    Strip String    ${fields}[2]
        ${message}=    Strip String    ${fields}[3]
        &{log_dict}=    Create Dictionary    timestamp=${timestamp}    level=${level}    code=${code}    message=${message}
        Append To List    ${parsed_logs}    ${log_dict}
    END
    ${count}=    Get Length    ${parsed_logs}
    Log    Parsed ${count} log entries
    Should Be Equal As Integers    ${count}    5
    Set Suite Variable    @{PARSED_LOGS}    @{parsed_logs}

Filter Error Logs
    @{errors}=    Create List
    FOR    ${log}    IN    @{PARSED_LOGS}
        ${level}=    Get From Dictionary    ${log}    level
        IF    '${level}' == 'ERROR'
            Append To List    ${errors}    ${log}
        END
    END
    ${error_count}=    Get Length    ${errors}
    Log    Error count: ${error_count}
    Should Be Equal As Integers    ${error_count}    2

Generate Report
    ${report}=    Set Variable    === LOG ANALYSIS REPORT ===\n
    FOR    ${log}    IN    @{PARSED_LOGS}
        ${timestamp}=    Get From Dictionary    ${log}    timestamp
        ${level}=    Get From Dictionary    ${log}    level
        ${code}=    Get From Dictionary    ${log}    code
        ${message}=    Get From Dictionary    ${log}    message
        ${line}=    Set Variable    [${timestamp}] ${level}: ${message} (${code})\n
        ${report}=    Set Variable    ${report}${line}
    END
    Log    ${report}
    Should Contain    ${report}    Navigation system offline
    Should Contain    ${report}    ERROR
